<form method="post" action="/admin/questions/{{ $item->id ?? '' }}">@csrf<label>Category<select name="category_id">@foreach($categories as $category)<option value="{{ $category->id }}" @selected(($item->category_id ?? 0)===$category->id)>{{ $category->name }}</option>@endforeach</select></label>
<label>Question<textarea name="text" required>{{ $item->text ?? '' }}</textarea></label><label>Type<select name="type">@foreach(['multiple_choice','true_false','single_answer'] as $type)<option @selected(($item->type ?? '')===$type)>{{ $type }}</option>@endforeach</select></label>
<label>Difficulty<select name="difficulty">@foreach(['easy','medium','hard'] as $difficulty)<option @selected(($item->difficulty ?? '')===$difficulty)>{{ $difficulty }}</option>@endforeach</select></label>
<label>Options (one per line; True and False for true/false)<textarea name="options">{{ isset($item) ? Illuminate\Support\Facades\DB::table('question_options')->where('question_id',$item->id)->orderBy('display_order')->pluck('text')->implode("\n") : '' }}</textarea></label>
<label>Correct answer (exact option text or single answer)<input name="correct_answer" value="{{ $item->correct_answer ?? (isset($item) ? Illuminate\Support\Facades\DB::table('question_options')->where('question_id',$item->id)->where('is_correct',true)->value('text') : '') }}" required></label>
<label>Explanation<textarea name="explanation">{{ $item->explanation ?? '' }}</textarea></label><label>Coin reward (blank uses category default)<input type="number" min="0" name="coin_reward" value="{{ $item->coin_reward ?? '' }}"></label>
